import org.springframework.beans.factory.annotation.Autowired
import org.springframework.stereotype.Controller

@Controller
class RootController {

    var baskets: List<Any> = listOf()              // bad, not private
    protected var baskets2: List<Any> = listOf()   // bad, not private
    internal var baskets3: List<Any> = listOf()    // bad, not private
    val baskets4: List<Any> = listOf()             // good, val (final)
    private var baskets5: List<Any> = listOf()     // good, private
    private val baskets6: List<Any> = listOf()     // good, private val

    @Autowired
    lateinit var baskets7: List<Any>               // allowed, injected
}

class RootController {
    var baskets: List<Any> = listOf() // good, not a shared object
}

import net.jcip.annotations.NotThreadSafe
import org.springframework.stereotype.Controller

@Controller
@NotThreadSafe
class RootController {
    var baskets: List<Any> = listOf() // allowed, specified NotThreadSafe
}

import org.springframework.stereotype.Controller

@Controller
class RootController {
    class Sub {
        var baskets: List<Any> = listOf() // allowed, nested class not known singleton
    }
    inner class Sub2 {
        var baskets: List<Any> = listOf() // allowed, inner class not known singleton
    }
}

import javax.inject.Inject
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component

@Component
abstract class Issue268 {

    @Autowired
    protected lateinit var quickSupport: Any

    @Value("\${config.url}")
    lateinit var configUrl: String

    @Inject
    lateinit var injectedService: Any
}

import org.springframework.context.annotation.Scope
import org.springframework.stereotype.Service

@Service
@Scope("request")
class RequestScopedService {
    var data: String = "" // allowed, request scoped
}

import org.springframework.stereotype.Service

@Service
class MyService {

    var mutableField: String = ""          // bad, not private
    lateinit var otherField: String        // bad, not private, not injected
    private var privateField: String = ""  // good, private
}

import org.springframework.stereotype.Repository

@Repository
class MyRepo {
    companion object {
        val CONSTANT: String = "ok"            // good, val
        var counter: Int = 0                   // bad, not private
        private var internalCounter: Int = 0   // good, private
    }
}

import org.springframework.web.bind.annotation.RestController

@RestController
class MyRestController {

    var cache: Map<String, Any> = mapOf() // bad, not private
    private var internalCache: Map<String, Any> = mapOf() // good, private
}

import org.springframework.context.annotation.Scope
import org.springframework.stereotype.Component

@Component
@Scope("prototype")
class PrototypeBean {
    var data: String = "" // allowed, prototype scoped
}

import org.springframework.context.annotation.Scope
import org.springframework.stereotype.Service
import org.springframework.web.bind.annotation.RequestMapping

@Service
@Scope("production")
@RequestMapping("request")
class ProductionScopedService {
    var notPrivate: String = "" // bad: non-private field in shared singleton
}
